import{_ as e,o as a,c as t,l as n,t as i,N as o}from"./chunks/framework.CMqbtke2.js";const u=JSON.parse('{"title":"hosts | x-cmd man (man5) | static table lookup for hostnames","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | hosts - static table lookup for hostnames","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"hosts | x-cmd man (man5) | static table lookup for hostnames"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | hosts - static table lookup for hostnames"}]]},"headers":[],"params":{"isMan":true,"man":"hosts","category":"man5","desc":"static table lookup for hostnames"},"relativePath":"man5/hosts.md","filePath":"man5/hosts.md"}'),h={name:"man5/hosts.md"},l={class:"visually-hidden"},r=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>hosts - static table lookup for hostnames</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/etc/hosts</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page describes the format of the <em>/etc/hosts</em> file. This file is a simple text file that associates IP addresses with hostnames, one line per IP address. For each host a single line should be present with the following information:</p><blockquote><p>IP_address canonical_hostname [aliases...]</p></blockquote><p>The IP address can conform to either IPv4 or IPv6. Fields of the entry are separated by any number of blanks and/or tab characters. Text from a &quot;#&quot; character until the end of the line is a comment, and is ignored. Host names may contain only alphanumeric characters, minus signs (&quot;-&quot;), and periods (&quot;.&quot;). They must begin with an alphabetic character and end with an alphanumeric character. Optional aliases provide for name changes, alternate spellings, shorter hostnames, or generic hostnames (for example, <em>localhost</em>). If required, a host may have two separate entries in this file; one for each version of the Internet Protocol (IPv4 and IPv6).</p><p>The Berkeley Internet Name Domain (BIND) Server implements the Internet name server for UNIX systems. It augments or replaces the <em>/etc/hosts</em> file or hostname lookup, and frees a host from relying on <em>/etc/hosts</em> being up to date and complete.</p><p>In modern systems, even though the host table has been superseded by DNS, it is still widely used for:</p><dl><dt><strong>bootstrapping</strong></dt><dd>Most systems have a small host table containing the name and address information for important hosts on the local network. This is useful when DNS is not running, for example during system bootup.</dd><dt><strong>NIS</strong></dt><dd>Sites that use NIS use the host table as input to the NIS host database. Even though NIS can be used with DNS, most NIS sites still use the host table with an entry for all local hosts as a backup.</dd><dt><strong>isolated nodes</strong></dt><dd>Very small sites that are isolated from the network use the host table instead of DNS. If the local information rarely changes, and the network is not connected to the Internet, DNS offers little advantage.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/hosts</em></p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Modifications to this file normally take effect immediately, except in cases where the file is cached by applications.</p><h3 id="historical-notes" tabindex="-1">Historical notes <a class="header-anchor" href="#historical-notes" aria-label="Permalink to &quot;Historical notes&quot;">​</a></h3><p>RFC 952 gave the original format for the host table, though it has since changed.</p><p>Before the advent of DNS, the host table was the only way of resolving hostnames on the fledgling Internet. Indeed, this file could be created from the official host data base maintained at the Network Information Control Center (NIC), though local changes were often required to bring it up to date regarding unofficial aliases and/or unknown hosts. The NIC no longer maintains the hosts.txt files, though looking around at the time of writing (circa 2000), there are historical hosts.txt files on the WWW. I just found three, from 92, 94, and 95.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The following lines are desirable for IPv4 capable hosts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   localhost</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 127.0.1.1 is often used for the FQDN of the machine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.1.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   thishost.example.org</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   thishost</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">192.168.1.10foo.example.orgfoo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">192.168.1.13bar.example.orgbar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">146.82.138.7master.debian.org</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  master</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">209.237.226.90</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  www.opensource.org</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The following lines are desirable for IPv6 capable hosts</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip6-localhost</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip6-loopback</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ff02::1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip6-allnodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ff02::2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip6-allrouters</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>hostname</strong>(1), <strong>resolver</strong>(3), <strong>host.conf</strong>(5), <strong>resolv.conf</strong>(5), <strong>resolver</strong>(5), <strong>hostname</strong>(7), <strong>named</strong>(8)</p><p>Internet RFC 952</p>`,23);function p(s,d,c,m,k,g){return a(),t("div",null,[n("h1",l,i(s.$params.man),1),r])}const b=e(h,[["render",p]]);export{u as __pageData,b as default};
